commands:
pwsh -NoLogo -NoProfile -Command "
\$ErrorActionPreference='Stop'
foreach (\$f in @('./podex.ps1','./api/_lib/pantry-store.ps1','./api/_lib/pantry-render.ps1')) {
  \$errs=\$null
  [System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path \$f), [ref]\$null, [ref]\$errs) | Out-Null
  if (\$errs) { Write-Host \"PARSE FAIL \$f\"; \$errs | ForEach-Object { Write-Host \$_.Message }; exit 1 } else { Write-Host \"parse ok: \$f\" }
}
"
